 public static void LangxiActualPrepareRandomDamageCold()
 {
  var(g,r)=Start();Reach(g,()=>Optional(g,"ol:langxi"));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");Reach(g,()=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="langxi-target")==true);Need(P(g)!.Choices.All(c=>c.Targets.Single()!=0&&V(g,c.Targets.Single()).Hp<=V(g,0).Hp),"Only actual living defined-HP others at or below the owner are offered.");g=Cold(g,r);var target=P(g)!.Choices.First().Targets.Single();var hp=V(g,target).Hp;Answer(g,c=>c.Targets.SequenceEqual([target]));Play(g);var paid=E<LangxiRandomResolvedEvent>(g).Single();Need(paid.Amount is >=0 and <=2&&V(g,target).Hp==hp-paid.Amount,"The accepted native choice samples the replayable 0..2 RNG exactly once and applies its actual damage.");Need(paid.Amount!=0||!E<DamageAppliedEvent>(g).Any(),"A zero result must not fabricate a positive damage event.");_=Cold(g,r);
 }
