 private static bool Optional(GameEngine g,string id)=>P(g)?.SkillPrompt?.SkillId==id&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];private static PendingDecision?P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p!=null);
    private static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}private static void Accept(GameEngine g,GameCommand c){var x=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(x.Accepted,(x.Error?.Message??"Rejected LiJue command.")+" "+Diagnostic(g));}private static void Answer(GameEngine g,Func<PromptChoice,bool>test){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(test).Id,g.Revision));}
private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static void Reach(GameEngine g,Func<bool>done){for(var i=0;i<200;i++){if(done())return;var p=P(g);if(p?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip")==true)Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else if(p is{Kind:DecisionKind.RescueDying,PlayerSeat:0})Answer(g,c=>c.Parameters.GetValueOrDefault("response")=="let-die");else if(p is{PlayerSeat:0,Kind:DecisionKind.PlayCard})End(g);else if(p is{PlayerSeat:0,Kind:DecisionKind.Nullification}&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("response")=="pass"))Answer(g,c=>c.Parameters.GetValueOrDefault("response")=="pass");else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Small native LiJue fixture exceeded its boundary. "+Diagnostic(g));}
    private static string Diagnostic(GameEngine g)=>System.Text.Json.JsonSerializer.Serialize(new{g.State,Pending=P(g),Stack=g.ResolutionStack.Select(f=>new{Type=f.GetType().Name,Frame=System.Text.Json.JsonSerializer.Serialize(f,f.GetType())}),Last12Events=g.Events.TakeLast(12).Select(e=>new{Type=e.Payload.GetType().Name,Fact=System.Text.Json.JsonSerializer.Serialize(e.Payload,e.Payload.GetType())}),Last12Movements=g.CardMovements.TakeLast(12),NativeUses=g.Events.Select(e=>e.Payload).Where(e=>e is CardUseDeclaredEvent or CardActionAcceptedEvent or CardUseFinishedEvent or YisuanNullificationQualifiedEvent).TakeLast(16).Select(e=>new{Type=e.GetType().Name,Fact=System.Text.Json.JsonSerializer.Serialize(e,e.GetType())})});
    private static void ReachYisuan(GameEngine g){Reach(g,()=>Optional(g,"ol:yisuan")||P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});Need(Optional(g,"ol:yisuan"),"The actual native used-Trick movement did not offer Yisuan before returning to Play. "+Diagnostic(g));}
    private static string State(GameEngine g)=>System.Text.Json.JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>System.Text.Json.JsonSerializer.Serialize(f,f.GetType())),Commands=CommandJson.Serialize(g.AcceptedCommands)});private static GameEngine Cold(GameEngine g,ContentRegistry r){var restored=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(restored),"Every private viewer, exact acquired lease/debt and once-paid native child survives cold replay.");return restored;}
 private static (GameEngine,ContentRegistry)Start(bool watch=false,bool death=false,bool terminal=false,bool counterspell=false,bool multi=false,bool ambush=false)
 {
